function todayStr() {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${d.getFullYear()}-${mm}-${dd}`;
}

function daysUntil(dateStr, recurring) {
  if (!dateStr) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const [y, m, d] = dateStr.split("-").map(Number);
  if (recurring) {
    // Cumpleaños: se repite cada año, el año guardado no importa.
    let target = new Date(today.getFullYear(), m - 1, d);
    if (target < today) target = new Date(today.getFullYear() + 1, m - 1, d);
    return Math.round((target - today) / 86400000);
  }
  // Pago / renovación: fecha exacta, el año sí importa.
  const target = new Date(y, m - 1, d);
  return Math.round((target - today) / 86400000);
}

function fmtDate(dateStr) {
  if (!dateStr) return "";
  const [y, m, d] = dateStr.split("-").map(Number);
  const meses = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  return `${d} ${meses[m - 1]}`;
}

function fmtDateFull(dateStr) {
  if (!dateStr) return "";
  const [y, m, d] = dateStr.split("-").map(Number);
  const meses = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  return `${d} ${meses[m - 1]} ${y}`;
}

function slugifyFileName(str) {
  return (
    String(str)
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-zA-Z0-9.]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .toLowerCase() || "archivo"
  );
}

const inputStyle = {
  width: "100%", padding: "10px 12px", border: "1px solid #DAD5C7",
  borderRadius: 6, fontSize: 14, background: "#FFFFFF", color: "#1B2A41",
};

function isoToDMY(iso) {
  if (!iso) return "";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
}

function dmyToISO(dmy) {
  const match = dmy.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!match) return null;
  const [, d, m, y] = match;
  const dd = Number(d), mm = Number(m), yy = Number(y);
  if (mm < 1 || mm > 12 || dd < 1 || dd > 31) return null;
  return `${yy}-${String(mm).padStart(2, "0")}-${String(dd).padStart(2, "0")}`;
}

function DateWithFallback({ value, onChange }) {
  const [manual, setManual] = useState(isoToDMY(value));
  const [manualError, setManualError] = useState(false);

  useEffect(() => {
    setManual(isoToDMY(value));
    setManualError(false);
  }, [value]);

  function commitManual(text) {
    setManual(text);
    if (text.trim() === "") {
      setManualError(false);
      onChange("");
      return;
    }
    const iso = dmyToISO(text);
    if (iso) {
      setManualError(false);
      onChange(iso);
    } else {
      setManualError(true);
    }
  }

  return (
    <div>
      <input type="date" value={value} onChange={(e) => onChange(e.target.value)} style={inputStyle} />
      <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 6 }}>
        <span style={{ fontSize: 11, color: "#8A8574" }}>o escribe:</span>
        <input
          value={manual}
          onChange={(e) => commitManual(e.target.value)}
          placeholder="dd/mm/aaaa"
          style={{ ...inputStyle, padding: "6px 10px", fontSize: 13, flex: 1 }}
        />
      </div>
      {manualError && <p style={{ color: "#B23A2E", fontSize: 11, margin: "4px 0 0" }}>Formato: dd/mm/aaaa</p>}
    </div>
  );
}

const MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];

function DateSelect({ value, onChange, yearsBack = 1, yearsForward = 10 }) {
  const parsed = value ? value.split("-").map(Number) : [null, null, null];
  const [local, setLocal] = useState({ y: parsed[0], m: parsed[1], d: parsed[2] });

  useEffect(() => {
    const p = value ? value.split("-").map(Number) : [null, null, null];
    setLocal({ y: p[0], m: p[1], d: p[2] });
  }, [value]);

  const thisYear = new Date().getFullYear();
  const years = [];
  for (let yy = thisYear - yearsBack; yy <= thisYear + yearsForward; yy++) years.push(yy);
  const days = Array.from({ length: 31 }, (_, i) => i + 1);

  function update(next) {
    setLocal(next);
    if (next.y && next.m && next.d) {
      onChange(`${next.y}-${String(next.m).padStart(2, "0")}-${String(next.d).padStart(2, "0")}`);
    }
  }

  return (
    <div style={{ display: "flex", gap: 6 }}>
      <select value={local.d || ""} onChange={(e) => update({ ...local, d: Number(e.target.value) || null })} style={{ ...inputStyle, flex: "0 0 68px" }}>
        <option value="">Día</option>
        {days.map((day) => <option key={day} value={day}>{day}</option>)}
      </select>
      <select value={local.m || ""} onChange={(e) => update({ ...local, m: Number(e.target.value) || null })} style={{ ...inputStyle, flex: 1 }}>
        <option value="">Mes</option>
        {MESES.map((mes, i) => <option key={mes} value={i + 1}>{mes}</option>)}
      </select>
      <select value={local.y || ""} onChange={(e) => update({ ...local, y: Number(e.target.value) || null })} style={{ ...inputStyle, flex: "0 0 84px" }}>
        <option value="">Año</option>
        {years.map((yr) => <option key={yr} value={yr}>{yr}</option>)}
      </select>
    </div>
  );
}

