const ESTADOS_PROSPECTO = ["No contactado", "Llamada", "Cita", "Se envía propuesta", "En proceso", "No interesado"];
const ESTADO_COLOR = {
  "No contactado": "#8A8574",
  "Llamada": "#4A6FA5",
  "Cita": "#C98A2C",
  "Se envía propuesta": "#9C7A3C",
  "En proceso": "#3E6259",
  "No interesado": "#B23A2E",
};

const emptyProspecto = { nombre: "", telefono: "", correo: "", estado: ESTADOS_PROSPECTO[0], notas: "" };

function Prospectos({ prospectos, onAdd, onUpdate, onRemove, onConvert }) {
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyProspecto);
  const [error, setError] = useState("");
  const [expandedId, setExpandedId] = useState(null);
  const [editDraft, setEditDraft] = useState(null);
  const [filter, setFilter] = useState(null);

  const funnelData = ESTADOS_PROSPECTO.map((e) => [e, prospectos.filter((p) => p.estado === e).length]);
  const visible = filter ? prospectos.filter((p) => p.estado === filter) : prospectos;

  function submitAdd(e) {
    e.preventDefault();
    if (!form.nombre.trim() || !form.telefono.trim()) {
      setError("Nombre y teléfono son obligatorios.");
      return;
    }
    onAdd({ ...form, id: Date.now().toString() });
    setForm(emptyProspecto);
    setError("");
    setShowForm(false);
  }

  function toggleExpand(p) {
    if (expandedId === p.id) { setExpandedId(null); setEditDraft(null); return; }
    const { id, ...rest } = p;
    setEditDraft(rest);
    setExpandedId(p.id);
  }

  function saveEdit(id) {
    onUpdate(id, editDraft);
    setExpandedId(null);
    setEditDraft(null);
  }

  return (
    <div>
      <div style={{ marginBottom: 20 }}>
        <h3 className="serif" style={{ fontSize: 15, fontWeight: 700, marginBottom: 10 }}>Embudo de prospectos</h3>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {funnelData.map(([estado, count]) => (
            <button
              key={estado}
              onClick={() => setFilter(filter === estado ? null : estado)}
              style={{
                display: "flex", alignItems: "center", gap: 6, fontSize: 12,
                border: filter === estado ? `1.5px solid ${ESTADO_COLOR[estado]}` : "1px solid #DAD5C7",
                background: filter === estado ? "#FFFFFF" : "#FFFFFF",
                borderRadius: 20, padding: "6px 10px",
              }}
            >
              <span style={{ width: 7, height: 7, borderRadius: 7, background: ESTADO_COLOR[estado] }} />
              {estado} <span style={{ color: "#5B5646", fontWeight: 600 }}>{count}</span>
            </button>
          ))}
        </div>
      </div>

      <button
        onClick={() => { setForm(emptyProspecto); setError(""); setShowForm(true); }}
        style={{
          display: "flex", alignItems: "center", gap: 8,
          background: "#1B2A41", color: "#F7F5F0", border: "none",
          borderRadius: 6, padding: "10px 16px", fontSize: 14, fontWeight: 600,
          marginBottom: 16,
        }}
      >
        <Plus size={16} /> Nuevo prospecto
      </button>

      {visible.length === 0 && <p style={{ color: "#8A8574", fontSize: 14 }}>Sin prospectos{filter ? ` en "${filter}"` : ""}.</p>}

      {visible.map((p) => {
        const isOpen = expandedId === p.id;
        return (
          <div key={p.id} style={{ borderBottom: "1px solid #E4E0D3" }}>
            <button
              onClick={() => toggleExpand(p)}
              style={{ width: "100%", background: "none", border: "none", textAlign: "left", padding: "14px 4px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 }}
            >
              <div>
                <div style={{ fontSize: 15, fontWeight: 600 }}>{p.nombre}</div>
                <div style={{ fontSize: 12, color: "#8A8574", marginTop: 2 }}>{p.telefono}</div>
                <div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 4 }}>
                  <span style={{ width: 7, height: 7, borderRadius: 7, background: ESTADO_COLOR[p.estado] }} />
                  <span style={{ fontSize: 12, color: "#5B5646" }}>{p.estado}</span>
                </div>
              </div>
              <ChevronDown size={18} color="#8A8574" style={{ flexShrink: 0, transform: isOpen ? "rotate(180deg)" : "none" }} />
            </button>

            {isOpen && editDraft && (
              <div style={{ padding: "4px 4px 20px" }}>
                <Field label="Nombre completo">
                  <input value={editDraft.nombre} onChange={(e) => setEditDraft((d) => ({ ...d, nombre: e.target.value }))} style={inputStyle} />
                </Field>
                <Field label="WhatsApp">
                  <input value={editDraft.telefono} onChange={(e) => setEditDraft((d) => ({ ...d, telefono: e.target.value }))} style={inputStyle} />
                </Field>
                <Field label="Correo electrónico">
                  <input type="email" value={editDraft.correo || ""} onChange={(e) => setEditDraft((d) => ({ ...d, correo: e.target.value }))} style={inputStyle} />
                </Field>
                <Field label="Estado">
                  <select value={editDraft.estado} onChange={(e) => setEditDraft((d) => ({ ...d, estado: e.target.value }))} style={inputStyle}>
                    {ESTADOS_PROSPECTO.map((e) => <option key={e} value={e}>{e}</option>)}
                  </select>
                </Field>
                <Field label="Notas">
                  <input value={editDraft.notas || ""} onChange={(e) => setEditDraft((d) => ({ ...d, notas: e.target.value }))} style={inputStyle} />
                </Field>
                <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                  <button onClick={() => saveEdit(p.id)} style={{ flex: 1, background: "#1B2A41", color: "#F7F5F0", border: "none", borderRadius: 6, padding: "12px", fontSize: 14, fontWeight: 600 }}>
                    Guardar cambios
                  </button>
                  <button onClick={() => onRemove(p.id)} style={{ background: "none", border: "1px solid #DAD5C7", color: "#B23A2E", borderRadius: 6, padding: "12px 14px" }}>
                    <Trash2 size={16} />
                  </button>
                </div>
                <button
                  onClick={() => onConvert(p)}
                  style={{ width: "100%", background: "none", border: "1px solid #3E6259", color: "#3E6259", borderRadius: 6, padding: "10px", fontSize: 13, fontWeight: 600 }}
                >
                  Convertir a cliente
                </button>
              </div>
            )}
          </div>
        );
      })}

      {showForm && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(27,42,65,0.4)", display: "flex", alignItems: "flex-end", justifyContent: "center", zIndex: 10 }}>
          <form onSubmit={submitAdd} style={{ background: "#F7F5F0", width: "100%", maxWidth: 480, borderRadius: "16px 16px 0 0", padding: 20, maxHeight: "88vh", overflowY: "auto" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <h2 className="serif" style={{ fontSize: 18, margin: 0 }}>Nuevo prospecto</h2>
              <button type="button" onClick={() => setShowForm(false)} style={{ background: "none", border: "none" }}><X size={20} /></button>
            </div>
            {error && <p style={{ color: "#B23A2E", fontSize: 13, marginTop: 0 }}>{error}</p>}
            <Field label="Nombre completo">
              <input value={form.nombre} onChange={(e) => setForm((f) => ({ ...f, nombre: e.target.value }))} style={inputStyle} />
            </Field>
            <Field label="WhatsApp">
              <input value={form.telefono} onChange={(e) => setForm((f) => ({ ...f, telefono: e.target.value }))} style={inputStyle} />
            </Field>
            <Field label="Correo electrónico">
              <input type="email" value={form.correo} onChange={(e) => setForm((f) => ({ ...f, correo: e.target.value }))} style={inputStyle} />
            </Field>
            <Field label="Estado">
              <select value={form.estado} onChange={(e) => setForm((f) => ({ ...f, estado: e.target.value }))} style={inputStyle}>
                {ESTADOS_PROSPECTO.map((e) => <option key={e} value={e}>{e}</option>)}
              </select>
            </Field>
            <Field label="Notas">
              <input value={form.notas} onChange={(e) => setForm((f) => ({ ...f, notas: e.target.value }))} style={inputStyle} />
            </Field>
            <button type="submit" style={{ width: "100%", background: "#1B2A41", color: "#F7F5F0", border: "none", borderRadius: 6, padding: "12px", fontSize: 14, fontWeight: 600 }}>
              Guardar prospecto
            </button>
          </form>
        </div>
      )}
    </div>
  );
}

function CondicionesGenerales({ docs, onUpload, onRemove, onView }) {
  const [query, setQuery] = useState("");
  const [ramo, setRamo] = useState(RAMOS[0]);
  const [aseguradora, setAseguradora] = useState(ASEGURADORAS[0]);
  const [pendingFile, setPendingFile] = useState(null);

  const filtered = docs.filter((d) => {
    const q = query.trim().toLowerCase();
    if (!q) return true;
    return (
      d.name.toLowerCase().includes(q) ||
      d.ramo.toLowerCase().includes(q) ||
      d.aseguradora.toLowerCase().includes(q)
    );
  });

  function handleAdd() {
    if (!pendingFile) return;
    onUpload({ file: pendingFile, ramo, aseguradora });
    setPendingFile(null);
  }

  return (
    <div>
      <p style={{ fontSize: 12, color: "#8A8574", marginTop: 0 }}>
        Sube aquí las condiciones generales por ramo y compañía. Toca el nombre para abrir el PDF.
      </p>

      <div style={{ background: "#FFFFFF", border: "1px solid #DAD5C7", borderRadius: 8, padding: 14, marginBottom: 20 }}>
        <div style={{ display: "flex", gap: 10, marginBottom: 10 }}>
          <div style={{ flex: 1 }}>
            <label style={{ display: "block", fontSize: 12, color: "#5B5646", marginBottom: 4, fontWeight: 500 }}>Ramo</label>
            <select value={ramo} onChange={(e) => setRamo(e.target.value)} style={inputStyle}>
              {RAMOS.map((r) => <option key={r} value={r}>{r}</option>)}
            </select>
          </div>
          <div style={{ flex: 1 }}>
            <label style={{ display: "block", fontSize: 12, color: "#5B5646", marginBottom: 4, fontWeight: 500 }}>Compañía</label>
            <select value={aseguradora} onChange={(e) => setAseguradora(e.target.value)} style={inputStyle}>
              {ASEGURADORAS.map((a) => <option key={a} value={a}>{a}</option>)}
            </select>
          </div>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <label style={{
            flex: 1, background: "#FFFFFF", border: "1px solid #DAD5C7", color: "#1B2A41", borderRadius: 6,
            padding: "10px 12px", fontSize: 13, cursor: "pointer", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
          }}>
            {pendingFile ? pendingFile.name : "Elegir archivo PDF..."}
            <input
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={(e) => setPendingFile(e.target.files[0] || null)}
            />
          </label>
          <button
            onClick={handleAdd}
            disabled={!pendingFile}
            style={{
              background: pendingFile ? "#1B2A41" : "#DAD5C7", color: "#F7F5F0", border: "none",
              borderRadius: 6, padding: "10px 16px", fontSize: 13, fontWeight: 600,
            }}
          >
            Agregar
          </button>
        </div>
      </div>

      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Buscar por ramo, compañía o nombre del archivo..."
        style={{ ...inputStyle, marginBottom: 14 }}
      />

      {filtered.length === 0 && (
        <p style={{ fontSize: 13, color: "#8A8574", textAlign: "center", padding: "20px 0" }}>
          {docs.length === 0 ? "Aún no subes condiciones generales." : "Sin resultados para tu búsqueda."}
        </p>
      )}

      {filtered.map((d) => (
        <div key={d.id} style={{
          display: "flex", justifyContent: "space-between", alignItems: "center",
          padding: "12px 0", borderBottom: "1px solid #E4E0D3", gap: 10,
        }}>
          <div style={{ minWidth: 0 }}>
            <button
              onClick={() => onView(d.path)}
              style={{
                fontSize: 14, fontWeight: 500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
                background: "none", border: "none", padding: 0, color: "#1B2A41", textDecoration: "underline",
                cursor: "pointer", display: "flex", alignItems: "center", gap: 6, maxWidth: "100%",
              }}
            >
              <FileText size={13} style={{ flexShrink: 0 }} />
              <span style={{ overflow: "hidden", textOverflow: "ellipsis" }}>{d.name}</span>
            </button>
            <div style={{ fontSize: 12, color: "#8A8574" }}>{d.aseguradora} · {d.ramo}</div>
          </div>
          <button
            onClick={() => onRemove(d.id)}
            style={{ background: "none", border: "1px solid #DAD5C7", borderRadius: 6, color: "#B23A2E", padding: "6px 10px", flexShrink: 0 }}
          >
            <Trash2 size={14} />
          </button>
        </div>
      ))}
    </div>
  );
}

