const DIAS_SEMANA = ["L", "M", "M", "J", "V", "S", "D"];
const MESES_LARGO = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];

function countBy(list, key) {
  const counts = {};
  list.forEach((item) => {
    const v = item[key] || "Sin especificar";
    counts[v] = (counts[v] || 0) + 1;
  });
  return Object.entries(counts).sort((a, b) => b[1] - a[1]);
}

const CHART_COLORS = ["#1B2A41", "#C98A2C", "#3E6259", "#B23A2E", "#6B7A8F", "#9C7A3C", "#4A6FA5", "#7A5C6E"];

function polarPoint(cx, cy, r, angleDeg) {
  const rad = ((angleDeg - 90) * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

function PieChart({ data, size = 180 }) {
  const total = data.reduce((s, [, n]) => s + n, 0) || 1;
  const cx = size / 2, cy = size / 2, r = size / 2 - 4;
  let angle = 0;
  const slices = data.map(([label, count], i) => {
    const sliceAngle = (count / total) * 360;
    const start = polarPoint(cx, cy, r, angle);
    const end = polarPoint(cx, cy, r, angle + sliceAngle);
    const largeArc = sliceAngle > 180 ? 1 : 0;
    const path = `M ${cx} ${cy} L ${start.x} ${start.y} A ${r} ${r} 0 ${largeArc} 1 ${end.x} ${end.y} Z`;
    angle += sliceAngle;
    return { path, color: CHART_COLORS[i % CHART_COLORS.length], label, count };
  });
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      {slices.map((s, i) => <path key={i} d={s.path} fill={s.color} stroke="#F7F5F0" strokeWidth="1.5" />)}
      <circle cx={cx} cy={cy} r={r * 0.55} fill="#F7F5F0" />
    </svg>
  );
}

function StatChart({ title, data }) {
  const [type, setType] = useState("pie");
  const max = Math.max(1, ...data.map(([, n]) => n));
  return (
    <div style={{ marginBottom: 28 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <h3 className="serif" style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>{title}</h3>
        <div style={{ display: "flex", gap: 2, background: "#E4E0D3", borderRadius: 6, padding: 2 }}>
          {[{ id: "pie", label: "Pastel" }, { id: "bar", label: "Barras" }].map((opt) => (
            <button
              key={opt.id}
              onClick={() => setType(opt.id)}
              style={{
                border: "none", borderRadius: 5, padding: "4px 10px", fontSize: 11, fontWeight: 600,
                background: type === opt.id ? "#1B2A41" : "transparent",
                color: type === opt.id ? "#F7F5F0" : "#5B5646",
              }}
            >
              {opt.label}
            </button>
          ))}
        </div>
      </div>

      {data.length === 0 && <p style={{ fontSize: 13, color: "#8A8574" }}>Sin datos todavía.</p>}

      {data.length > 0 && type === "pie" && (
        <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
          <PieChart data={data} />
          <div style={{ flex: 1 }}>
            {data.map(([label, count], i) => (
              <div key={label} style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, marginBottom: 6 }}>
                <span style={{ width: 8, height: 8, borderRadius: 8, background: CHART_COLORS[i % CHART_COLORS.length], flexShrink: 0 }} />
                <span style={{ flex: 1 }}>{label}</span>
                <span style={{ color: "#5B5646", fontWeight: 600 }}>{count}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {data.length > 0 && type === "bar" && data.map(([label, count], i) => (
        <div key={label} style={{ marginBottom: 8 }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, marginBottom: 3 }}>
            <span>{label}</span>
            <span style={{ color: "#5B5646", fontWeight: 600 }}>{count}</span>
          </div>
          <div style={{ background: "#E4E0D3", borderRadius: 4, height: 8 }}>
            <div style={{
              width: `${(count / max) * 100}%`, background: CHART_COLORS[i % CHART_COLORS.length],
              height: "100%", borderRadius: 4,
            }} />
          </div>
        </div>
      ))}
    </div>
  );
}

function buildCalendarEvents(clients, year, month) {
  // month: 0-indexed. Devuelve { "YYYY-MM-DD": [{tone, client, label}] }
  const events = {};
  function add(dateStr, tone, client, label) {
    events[dateStr] = events[dateStr] || [];
    events[dateStr].push({ tone, client: client.nombre, label });
  }
  clients.forEach((c) => {
    if (c.fechaPago) {
      const [y, m, d] = c.fechaPago.split("-").map(Number);
      if (y === year && m - 1 === month) add(c.fechaPago, "pago", c, "Pago");
    }
    if (c.fechaRenovacion) {
      const [y, m, d] = c.fechaRenovacion.split("-").map(Number);
      if (y === year && m - 1 === month) add(c.fechaRenovacion, "renovacion", c, "Renovación");
    }
    if (c.fechaCumple) {
      const [, m, d] = c.fechaCumple.split("-").map(Number);
      if (m - 1 === month) {
        const dateStr = `${year}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
        add(dateStr, "cumple", c, "Cumpleaños");
      }
    }
  });
  return events;
}

const TONE_COLOR = { pago: "#B23A2E", renovacion: "#C98A2C", cumple: "#3E6259" };

function Calendar({ clients }) {
  const today = new Date();
  const [viewYear, setViewYear] = useState(today.getFullYear());
  const [viewMonth, setViewMonth] = useState(today.getMonth());
  const [selectedDate, setSelectedDate] = useState(null);

  const events = useMemo(() => buildCalendarEvents(clients, viewYear, viewMonth), [clients, viewYear, viewMonth]);

  const firstOfMonth = new Date(viewYear, viewMonth, 1);
  const startWeekday = (firstOfMonth.getDay() + 6) % 7; // lunes = 0
  const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();

  const cells = [];
  for (let i = 0; i < startWeekday; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) cells.push(d);

  function changeMonth(delta) {
    let m = viewMonth + delta, y = viewYear;
    if (m < 0) { m = 11; y -= 1; }
    if (m > 11) { m = 0; y += 1; }
    setViewMonth(m); setViewYear(y);
    setSelectedDate(null);
  }

  const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
  const selectedEvents = selectedDate ? (events[selectedDate] || []) : [];

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <button onClick={() => changeMonth(-1)} style={{ background: "none", border: "1px solid #DAD5C7", borderRadius: 6, padding: "4px 10px", fontSize: 14 }}>‹</button>
        <h3 className="serif" style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>{MESES_LARGO[viewMonth]} {viewYear}</h3>
        <button onClick={() => changeMonth(1)} style={{ background: "none", border: "1px solid #DAD5C7", borderRadius: 6, padding: "4px 10px", fontSize: 14 }}>›</button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 2, marginBottom: 4 }}>
        {DIAS_SEMANA.map((d, i) => (
          <div key={i} style={{ textAlign: "center", fontSize: 11, color: "#8A8574", fontWeight: 600 }}>{d}</div>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", gap: 2 }}>
        {cells.map((day, i) => {
          if (day === null) return <div key={i} />;
          const dateStr = `${viewYear}-${String(viewMonth + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
          const dayEvents = events[dateStr] || [];
          const isToday = dateStr === todayStr;
          const isSelected = dateStr === selectedDate;
          return (
            <button
              key={i}
              onClick={() => setSelectedDate(dayEvents.length ? dateStr : null)}
              style={{
                aspectRatio: "1", background: isSelected ? "#1B2A41" : "transparent",
                border: isToday ? "1px solid #C98A2C" : "1px solid transparent",
                borderRadius: 6, display: "flex", flexDirection: "column", alignItems: "center",
                justifyContent: "center", gap: 2, padding: 2,
              }}
            >
              <span style={{ fontSize: 12, color: isSelected ? "#F7F5F0" : "#1B2A41" }}>{day}</span>
              <span style={{ display: "flex", gap: 2 }}>
                {dayEvents.slice(0, 3).map((ev, j) => (
                  <span key={j} style={{ width: 4, height: 4, borderRadius: 4, background: TONE_COLOR[ev.tone] }} />
                ))}
              </span>
            </button>
          );
        })}
      </div>

      {selectedEvents.length > 0 && (
        <div style={{ marginTop: 16, borderTop: "1px solid #E4E0D3", paddingTop: 12 }}>
          {selectedEvents.map((ev, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 6 }}>
              <span style={{ width: 8, height: 8, borderRadius: 8, background: TONE_COLOR[ev.tone], flexShrink: 0 }} />
              <span>{ev.client} · {ev.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const DIAS_LARGO = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"];
const TIPOS_ACTIVIDAD = ["Llamada", "Visita", "Reunión", "Tarea", "Otro"];

function toISODate(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function mondayOf(date) {
  const d = new Date(date);
  const day = (d.getDay() + 6) % 7; // lunes = 0
  d.setDate(d.getDate() - day);
  d.setHours(0, 0, 0, 0);
  return d;
}

function getRemindersForDate(clients, dateStr) {
  const [, month, day] = dateStr.split("-").map(Number);
  const items = [];
  clients.forEach((c) => {
    if (c.fechaPago === dateStr) items.push({ tone: "pago", label: "Pago", client: c });
    if (c.fechaRenovacion === dateStr) items.push({ tone: "renovacion", label: "Renovación", client: c });
    if (c.fechaCumple) {
      const [, m, d] = c.fechaCumple.split("-").map(Number);
      if (m === month && d === day) items.push({ tone: "cumple", label: "Cumpleaños", client: c });
    }
  });
  return items;
}

function Planificador({ clients, activities, onAddActivity, onRemoveActivity }) {
  const [weekStart, setWeekStart] = useState(() => mondayOf(new Date()));
  const [addingFor, setAddingFor] = useState(null);
  const [draft, setDraft] = useState({ hora: "", tipo: TIPOS_ACTIVIDAD[0], descripcion: "", clienteId: "" });

  const weekDates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + i);
    return d;
  });

  function changeWeek(delta) {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + delta * 7);
    setWeekStart(d);
    setAddingFor(null);
  }

  function openAdd(dateStr) {
    setAddingFor(dateStr);
    setDraft({ hora: "", tipo: TIPOS_ACTIVIDAD[0], descripcion: "", clienteId: "" });
  }

  function submitAdd(dateStr) {
    if (!draft.descripcion.trim()) return;
    onAddActivity({ ...draft, id: Date.now().toString(), fecha: dateStr });
    setAddingFor(null);
  }

  const today = toISODate(new Date());
  const rangeLabel = `${weekDates[0].getDate()} ${MESES_LARGO[weekDates[0].getMonth()].slice(0, 3)} – ${weekDates[6].getDate()} ${MESES_LARGO[weekDates[6].getMonth()].slice(0, 3)}`;

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
        <button onClick={() => changeWeek(-1)} style={{ background: "none", border: "1px solid #DAD5C7", borderRadius: 6, padding: "4px 10px" }}>‹</button>
        <span style={{ fontSize: 13, fontWeight: 600, color: "#5B5646" }}>{rangeLabel}</span>
        <button onClick={() => changeWeek(1)} style={{ background: "none", border: "1px solid #DAD5C7", borderRadius: 6, padding: "4px 10px" }}>›</button>
      </div>

      {weekDates.map((date, i) => {
        const dateStr = toISODate(date);
        const isToday = dateStr === today;
        const reminders = getRemindersForDate(clients, dateStr);
        const dayActivities = activities.filter((a) => a.fecha === dateStr).sort((a, b) => (a.hora || "").localeCompare(b.hora || ""));
        const isAdding = addingFor === dateStr;

        return (
          <div key={dateStr} style={{ marginBottom: 18, borderBottom: "1px solid #E4E0D3", paddingBottom: 14 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span className="serif" style={{ fontSize: 14, fontWeight: 700, color: isToday ? "#C98A2C" : "#1B2A41" }}>
                  {DIAS_LARGO[i]} {date.getDate()}
                </span>
                {isToday && <span style={{ fontSize: 10, color: "#C98A2C", fontWeight: 700 }}>HOY</span>}
              </div>
              <button
                onClick={() => (isAdding ? setAddingFor(null) : openAdd(dateStr))}
                style={{ background: "none", border: "none", color: "#1B2A41" }}
              >
                <Plus size={16} />
              </button>
            </div>

            {reminders.length === 0 && dayActivities.length === 0 && !isAdding && (
              <p style={{ fontSize: 12, color: "#B0AB9A", margin: 0 }}>Sin actividades.</p>
            )}

            {reminders.map((r, j) => (
              <div key={`r${j}`} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 6 }}>
                <span style={{ width: 8, height: 8, borderRadius: 8, background: TONE_COLOR[r.tone], flexShrink: 0 }} />
                <span>{r.client.nombre} · {r.label}</span>
              </div>
            ))}

            {dayActivities.map((a) => {
              const client = clients.find((c) => c.id === a.clienteId);
              return (
                <div key={a.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 6 }}>
                  <span style={{ width: 8, height: 8, borderRadius: 8, background: "#4A6FA5", flexShrink: 0 }} />
                  <span style={{ flex: 1 }}>
                    {a.hora && `${a.hora} · `}{a.tipo}: {a.descripcion}{client ? ` (${client.nombre})` : ""}
                  </span>
                  <button onClick={() => onRemoveActivity(a.id)} style={{ background: "none", border: "none", color: "#B0AB9A" }}>
                    <X size={13} />
                  </button>
                </div>
              );
            })}

            {isAdding && (
              <div style={{ background: "#FFFFFF", border: "1px solid #DAD5C7", borderRadius: 8, padding: 12, marginTop: 8 }}>
                <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                  <input
                    type="time"
                    value={draft.hora}
                    onChange={(e) => setDraft((d) => ({ ...d, hora: e.target.value }))}
                    style={{ ...inputStyle, flex: "0 0 100px" }}
                  />
                  <select
                    value={draft.tipo}
                    onChange={(e) => setDraft((d) => ({ ...d, tipo: e.target.value }))}
                    style={{ ...inputStyle, flex: 1 }}
                  >
                    {TIPOS_ACTIVIDAD.map((t) => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <input
                  value={draft.descripcion}
                  onChange={(e) => setDraft((d) => ({ ...d, descripcion: e.target.value }))}
                  placeholder="Descripción..."
                  style={{ ...inputStyle, marginBottom: 8 }}
                />
                <select
                  value={draft.clienteId}
                  onChange={(e) => setDraft((d) => ({ ...d, clienteId: e.target.value }))}
                  style={{ ...inputStyle, marginBottom: 8 }}
                >
                  <option value="">Sin cliente relacionado</option>
                  {clients.map((c) => <option key={c.id} value={c.id}>{c.nombre}</option>)}
                </select>
                <button
                  onClick={() => submitAdd(dateStr)}
                  style={{ width: "100%", background: "#1B2A41", color: "#F7F5F0", border: "none", borderRadius: 6, padding: "10px", fontSize: 13, fontWeight: 600 }}
                >
                  Agregar
                </button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function Dashboard({ clients }) {
  const byRamo = countBy(clients, "ramo");
  const byAseguradora = countBy(clients, "aseguradora");
  const topRamo = byRamo[0];
  const topPercent = topRamo && clients.length ? Math.round((topRamo[1] / clients.length) * 100) : 0;
  return (
    <div>
      <p style={{ fontSize: 13, color: "#5B5646", marginTop: 0, marginBottom: 20 }}>
        {clients.length} póliza{clients.length === 1 ? "" : "s"} en total.
      </p>

      {topRamo && (
        <div style={{
          background: "#1B2A41", color: "#F7F5F0", borderRadius: 10,
          padding: "16px 18px", marginBottom: 24,
        }}>
          <div style={{ fontSize: 11, letterSpacing: 0.5, color: "#C98A2C", fontWeight: 700, textTransform: "uppercase" }}>
            Tu ramo líder
          </div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginTop: 4 }}>
            <span className="serif" style={{ fontSize: 22, fontWeight: 700 }}>{topRamo[0]}</span>
            <span style={{ fontSize: 13, color: "#D8D3C4" }}>{topRamo[1]} póliza{topRamo[1] === 1 ? "" : "s"} · {topPercent}% de tu cartera</span>
          </div>
        </div>
      )}

      <StatChart title="Por ramo" data={byRamo} />
      <StatChart title="Por aseguradora" data={byAseguradora} />
      <h3 className="serif" style={{ fontSize: 15, fontWeight: 700, marginBottom: 10 }}>Calendario de recordatorios</h3>
      <Calendar clients={clients} />
    </div>
  );
}

