      const ext = file.name.includes(".") ? file.name.split(".").pop() : "jpg";
      const path = `${user.id}/foto.${ext}`;
      const { error: upErr } = await supabase.storage.from(TARJETAS_BUCKET).upload(path, file, { upsert: true });
